package ai.arena.client;

import org.json.JSONObject;

/** JVM-only policy tests. No WebView, account traffic, Android package or signing. */
public final class RouteChecks {
    static int count=0;
    interface Work { void run() throws Exception; }
    static void check(String name,Work work) throws Exception { work.run();count++;System.out.println("PASS "+name); }
    static void yes(boolean value) { if(!value)throw new AssertionError("condition failed"); }
    static void rejects(Work work) throws Exception { boolean failed=false;try{work.run();}catch(Exception expected){failed=true;}yes(failed); }
    static JSONObject account() throws Exception { return new JSONObject().put("id","a").put("email","a@example.invalid").put("proxy","vless://fixture").put("proxyIp","203.0.113.2").put("nodeId","one").put("region","JP").put("xout","{}"); }
    static JSONObject begin(JSONObject a,String op) throws Exception { return new JSONObject().put("op",op).put("kind","signup").put("email","a@example.invalid").put("ip","203.0.113.9").put("expected",new JSONObject(a.toString())); }
    static JSONObject finish(String ip) throws Exception { return new JSONObject().put("op","finish").put("email","a@example.invalid").put("ticket","task").put("ip",ip); }
    public static void main(String[] args) throws Exception {
        check("explicit node recovery and no legacy opt-in",()->{JSONObject a=account().put("routeAuto",false);yes(!AuthRouteState.recover(a));AuthRouteState.prefs(a,"node");yes(AuthRouteState.recover(a));yes(!a.optBoolean("routeAuto"));});
        check("direct and proxy modes stay fixed",()->{for(String mode:new String[]{"proxy","direct"}){JSONObject a=account();AuthRouteState.prefs(a,mode);yes(!AuthRouteState.recover(a));}});
        check("invalid strategy rejected",()->rejects(()->AuthRouteState.prefs(account(),"unknown")));
        check("canonical fingerprint ordering",()->{JSONObject a=account().put("fp",new JSONObject().put("b",2).put("a",1)),b=account().put("fp",new JSONObject().put("a",1).put("b",2));yes(AuthRouteState.signature(a).equals(AuthRouteState.signature(b)));});
        check("lock precedes actual IP detection",()->{JSONObject a=account(),request=begin(a,"prepare");request.remove("ip");AuthRouteState.task(a,request,1000,"task","env");yes(AuthRouteState.locked(a));yes(a.optJSONObject("routeAuth").optBoolean("preparing"));rejects(()->AuthRouteState.task(a,finish("203.0.113.9"),2000,"unused","env"));});
        check("prepared lease seals the actual IP without changing task",()->{JSONObject a=account();AuthRouteState.task(a,begin(a,"prepare"),1000,"task","env");AuthRouteState.task(a,begin(a,"begin"),2000,"unused","env");yes(!a.optJSONObject("routeAuth").optBoolean("preparing"));yes("task".equals(a.optJSONObject("routeAuth").optString("ticket")));AuthRouteState.task(a,finish("203.0.113.9"),3000,"unused","env");yes(!AuthRouteState.locked(a));});
        check("all critical settings are locked",()->{JSONObject a=account();AuthRouteState.task(a,begin(a,"begin"),1000,"task","env");for(String field:AuthRouteState.CRITICAL)rejects(()->AuthRouteState.assertChange(a,new JSONObject().put(field,"changed")));});
        check("unrelated labels remain writable",()->{JSONObject a=account();AuthRouteState.task(a,begin(a,"begin"),1000,"task","env");AuthRouteState.assertChange(a,new JSONObject().put("name","new label"));});
        check("target mailbox cannot drift",()->{JSONObject a=account();AuthRouteState.task(a,begin(a,"begin"),1000,"task","env");rejects(()->AuthRouteState.assertChange(a,new JSONObject().put("email","b@example.invalid")));});
        check("expiry does not unlock the route",()->{JSONObject a=account();AuthRouteState.task(a,begin(a,"begin"),1000,"task","env");yes(AuthRouteState.status(a,2000000).optBoolean("expired"));rejects(()->AuthRouteState.task(a,finish("203.0.113.9"),2000000,"unused","env"));yes(AuthRouteState.locked(a));});
        check("wrong actual IP cannot finish",()->{JSONObject a=account();AuthRouteState.task(a,begin(a,"begin"),1000,"task","env");rejects(()->AuthRouteState.task(a,finish("203.0.113.8"),2000,"unused","env"));});
        check("changed browser environment cannot finish",()->{JSONObject a=account();AuthRouteState.task(a,begin(a,"begin"),1000,"task","env");rejects(()->AuthRouteState.task(a,finish("203.0.113.9"),2000,"unused","other"));});
        check("different service identity cannot finish",()->{JSONObject a=account();AuthRouteState.task(a,begin(a,"begin"),1000,"task","env");rejects(()->AuthRouteState.task(a,finish("203.0.113.9").put("email","b@example.invalid"),2000,"unused","env"));});
        check("route mutations outside the task are detected",()->{JSONObject a=account();AuthRouteState.task(a,begin(a,"begin"),1000,"task","env");a.put("region","US");rejects(()->AuthRouteState.task(a,finish("203.0.113.9"),2000,"unused","env"));});
        check("configuration changes during preparation are rejected",()->{JSONObject a=account(),request=begin(a,"begin");a.put("proxyIp","203.0.113.3");rejects(()->AuthRouteState.task(a,request,1000,"task","env"));});
        check("mail step is durable metadata and stays locked",()->{JSONObject a=account();AuthRouteState.task(a,begin(a,"begin"),1000,"task","env");AuthRouteState.task(a,new JSONObject().put("op","stage").put("kind","signup").put("ticket","task").put("stage","waiting-mail"),2000,"unused","env");JSONObject restored=new JSONObject(a.toString());yes("waiting-mail".equals(AuthRouteState.status(restored,3000).optString("stage")));yes(AuthRouteState.locked(restored));});
        check("stale cancellation never unlocks another task",()->{JSONObject a=account();AuthRouteState.task(a,begin(a,"begin"),1000,"task","env");rejects(()->AuthRouteState.task(a,new JSONObject().put("op","cancel").put("ticket","stale"),2000,"unused","env"));yes(AuthRouteState.locked(a));});
        check("explicit cancellation works after expiry",()->{JSONObject a=account();AuthRouteState.task(a,begin(a,"begin"),1000,"task","env");AuthRouteState.task(a,new JSONObject().put("op","cancel").put("ticket","task"),2000000,"unused","env");yes(!AuthRouteState.locked(a));});
        check("HTTP 429 uses Retry-After, not node failure",()->{JSONObject r=RouteSupport.blocked(new JSONObject().put("status",429).put("retry","90"));yes("rate-limit".equals(r.optString("kind")));yes(r.optLong("retryAfterMs")==90000);yes(r.optBoolean("reachable"));});
        check("challenge HTML is not a transport failure",()->{JSONObject r=RouteSupport.blocked(new JSONObject().put("status",200).put("text","<!doctype html><html>challenge</html>"));yes("verification".equals(r.optString("kind")));});
        check("HTTP 503 is classified as a server problem",()->{yes("service".equals(RouteSupport.blocked(new JSONObject().put("status",503)).optString("kind")));});
        check("renderer expectedConfig (JS JSON.stringify) matches native route config",()->{JSONObject a=account().put("xout","{\"path\":\"/ws?ed=2048\"}");String js="[\"vless://fixture\",\"203.0.113.2\",\"one\",\"JP\",\"{\\\"path\\\":\\\"/ws?ed=2048\\\"}\",\"\"]";yes(js.equals(AuthRouteState.jsSignature(a)));yes(AuthRouteState.sameConfig(a,js));yes(AuthRouteState.sameConfig(a,AuthRouteState.signature(a)));yes(!AuthRouteState.sameConfig(new JSONObject(a.toString()).put("nodeId","two"),js));});
        check("probe receipts bind outbound configuration too",()->{JSONObject a=account(),b=new JSONObject(a.toString()).put("xout","changed");yes(!AuthRouteState.probeKey(a).equals(AuthRouteState.probeKey(b)));});
        check("draft opening never creates a target",()->{java.util.Map<String,JSONObject> list=new java.util.HashMap<>();RouteDraftState d=new RouteDraftState(list::get);RouteDraftState.Draft item=d.open("frame-A","",1000);yes(item.target==null);yes(list.isEmpty());});
        check("draft authority binds caller and target",()->{JSONObject a=account();RouteDraftState d=new RouteDraftState(id->"a".equals(id)?a:null);RouteDraftState.Draft item=d.open("frame-A","a",1000);yes(d.get("frame-A",item.id,2000,false).target==a);rejects(()->d.get("frame-B",item.id,2000,false));});
        check("removed draft target never becomes a new account",()->{java.util.Map<String,JSONObject> list=new java.util.HashMap<>();list.put("a",account());RouteDraftState d=new RouteDraftState(list::get);RouteDraftState.Draft item=d.open("frame-A","a",1000);list.clear();rejects(()->d.get("frame-A",item.id,2000,false));});
        check("route change makes existing draft stale",()->{JSONObject a=account();RouteDraftState d=new RouteDraftState(id->a);RouteDraftState.Draft item=d.open("frame-A","a",1000);a.put("proxyIp","changed");rejects(()->d.get("frame-A",item.id,2000,false));});
        check("credential change makes existing draft stale",()->{JSONObject a=account();RouteDraftState d=new RouteDraftState(id->a);RouteDraftState.Draft item=d.open("frame-A","a",1000);a.put("pw","new-encrypted-value");rejects(()->d.get("frame-A",item.id,2000,false));});
        check("status refresh does not invalidate draft",()->{JSONObject a=account();RouteDraftState d=new RouteDraftState(id->a);RouteDraftState.Draft item=d.open("frame-A","a",1000);a.put("status",new JSONObject().put("quota",7));yes(d.get("frame-A",item.id,2000,false)==item);});
        check("receipts for different drafts have different owners",()->{JSONObject a=account();RouteDraftState d=new RouteDraftState(id->a);yes(!d.open("frame-A","a",1000).proofOwner.equals(d.open("frame-A","a",1000).proofOwner));});
        check("closed and expired drafts cannot be reused",()->{RouteDraftState d=new RouteDraftState(id->null);RouteDraftState.Draft item=d.open("frame-A","",1000);d.close("frame-A",item.id,2000);rejects(()->d.get("frame-A",item.id,3000,false));RouteDraftState.Draft expired=d.open("frame-A","",1000);rejects(()->d.get("frame-A",expired.id,1000000,false));});
        check("busy draft is retained until native commit resolves",()->{RouteDraftState d=new RouteDraftState(id->null);RouteDraftState.Draft item=d.open("frame-A","",1000);item.busy=true;rejects(()->d.close("frame-A",item.id,2000));yes(d.get("frame-A",item.id,2000,false)==item);});
        check("successful draft status keeps exact saved identity",()->{JSONObject a=account();RouteDraftState d=new RouteDraftState(id->a);RouteDraftState.Draft item=d.open("frame-A","",1000);item.saved=a;item.savedHash="hash";yes(d.get("frame-A",item.id,2000,true).saved==a);rejects(()->d.get("frame-A",item.id,2000,false));});
        check("request digest is canonical and does not store plaintext",()->{JSONObject a=new JSONObject().put("email","a@example.invalid").put("password","fixture-password"),b=new JSONObject().put("password","fixture-password").put("email","a@example.invalid");yes(RouteDraftState.digest(a).equals(RouteDraftState.digest(b)));yes(RouteDraftState.digest(a).length()==64);yes(!RouteDraftState.digest(a).contains("fixture-password"));});
        System.out.println("{\"passed\":"+count+",\"network\":false,\"androidRuntime\":false}");
    }
}
